{
  "cases": [
    {
      "title": "Verificación de restricciones de chat para rol pending",
      "preconditions": [
        "El usuario está autenticado con rol `pending`.",
        "El usuario ha iniciado sesión por primera vez y requiere aprobación manual."
      ],
      "steps": [
        "Intentar iniciar una sesión de chat.",
        "Observar la interfaz de chat."
      ],
      "expected": "El chat no debe ser accesible; el usuario debe ver únicamente la pantalla de espera.",
      "evidence": [
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "Solo puede ver la pantalla de espera; no puede usar el chat"
        }
      ]
    },
    {
      "title": "Verificación de habilitación de chat tras cambio de rol a user",
      "preconditions": [
        "El usuario tiene rol `user`.",
        "El usuario ha iniciado sesión."
      ],
      "steps": [
        "Intentar iniciar una sesión de chat.",
        "Observar la interfaz de chat."
      ],
      "expected": "El chat debe ser accesible y funcional.",
      "evidence": [
        {
          "passage_id": "Pbef6e2a6f4a41e236e72a901",
          "quote": "Usuario activo: Chat, upload de archivos, uso de bases de conocimiento según permisos"
        }
      ]
    }
  ],
  "open_questions": [
    "¿Qué sucede si un admin intenta cambiar el rol de un usuario `pending` a `user` sin que el usuario haya iniciado sesión?",
    "¿Existen otros estados intermedios entre `pending` y `user` que puedan afectar el acceso al chat?"
  ]
}
